package minio

import (
	"bytes"
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"

	minioclient "github.com/minio/minio-go/v7"
)

// This verifies real object storage with existing media bytes. It does not
// claim those bytes were generated by a supplier.
func TestRealObjectStorageMediaRoundTripIntegration(t *testing.T) {
	if os.Getenv("SUB2VIDEO_RUN_INTEGRATION") != "1" {
		t.Skip("set SUB2VIDEO_RUN_INTEGRATION=1 and isolated MinIO settings")
	}
	cfg := Config{Endpoint: os.Getenv("SUB2VIDEO_TEST_MINIO_ENDPOINT"), AccessKey: os.Getenv("SUB2VIDEO_TEST_MINIO_ACCESS_KEY"), SecretKey: os.Getenv("SUB2VIDEO_TEST_MINIO_SECRET_KEY"), Bucket: os.Getenv("SUB2VIDEO_TEST_MINIO_BUCKET"), UseSSL: os.Getenv("SUB2VIDEO_TEST_MINIO_SSL") == "true"}
	if cfg.Endpoint == "" || cfg.AccessKey == "" || cfg.SecretKey == "" || cfg.Bucket == "" {
		t.Skip("dedicated MinIO endpoint/access key/secret/bucket are required")
	}
	if !strings.Contains(cfg.Bucket, "test") {
		t.Fatal("refusing writes to a bucket without test in its name")
	}
	fixture := os.Getenv("SUB2VIDEO_TEST_MEDIA_FILE")
	if fixture == "" {
		t.Skip("SUB2VIDEO_TEST_MEDIA_FILE must identify an existing licensed video fixture")
	}
	content, err := os.ReadFile(fixture)
	if err != nil || len(content) == 0 {
		t.Fatal("video fixture unavailable or empty")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	c := New(cfg)
	if err := c.EnsureBucket(ctx); err != nil {
		t.Fatal("cannot access isolated MinIO bucket")
	}
	nonce := make([]byte, 16)
	if _, err := rand.Read(nonce); err != nil {
		t.Fatal(err)
	}
	key := "integration/" + hex.EncodeToString(nonce) + "/licensed-fixture.webm"
	t.Cleanup(func() {
		cleanup, done := context.WithTimeout(context.Background(), 10*time.Second)
		defer done()
		if err := c.cli.RemoveObject(cleanup, cfg.Bucket, key, minioclient.RemoveObjectOptions{}); err != nil {
			t.Error("failed to remove this test's exact object key")
		}
	})
	if err := c.PutObject(ctx, key, content, "video/webm"); err != nil {
		t.Fatal("MinIO upload failed")
	}
	signed, err := c.SignGetURL(ctx, key, time.Minute)
	if err != nil {
		t.Fatal("MinIO signing failed")
	}
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, signed, nil)
	if err != nil {
		t.Fatal("invalid signed URL")
	}
	res, err := http.DefaultClient.Do(request)
	if err != nil {
		t.Fatal("signed download failed")
	}
	defer res.Body.Close()
	got, err := io.ReadAll(io.LimitReader(res.Body, int64(len(content)+1)))
	if err != nil || res.StatusCode != http.StatusOK || !bytes.Equal(content, got) {
		t.Fatal("download did not preserve the complete video bytes")
	}
	if !strings.HasPrefix(res.Header.Get("Content-Type"), "video/") {
		t.Fatal("download is not served as video")
	}
	// Private media must not become readable merely by stripping the signature.
	unsigned, _ := http.NewRequestWithContext(ctx, http.MethodGet, c.ObjectURL(key), nil)
	denied, err := http.DefaultClient.Do(unsigned)
	if err != nil {
		t.Fatal("unsigned access check failed")
	}
	defer denied.Body.Close()
	if denied.StatusCode != http.StatusForbidden {
		t.Fatalf("unsigned download must be forbidden; status=%d", denied.StatusCode)
	}
	t.Logf("real MinIO signed download: bytes=%d sha256=%x; unsigned=403; exact test object cleaned", len(got), sha256.Sum256(got))
}
